export const DONATION_GUIDES:DonationGuide[] = [
  {
    slug:'find-blood-donors-near-you',title:'Find blood donors near you, with a clearer plan.',category:'Finding donors',
    description:'A practical guide to searching by country, city and blood group, understanding donor listings and moving from a search result to hospital-led coordination.',
    lead:'A useful donor search starts with the hospital’s requirement and ends with a confirmed plan. Here is how to make the steps between them easier.',
    chapters:[
      {title:'Begin with a specific hospital requirement',text:'Before choosing a filter, ask the treating team what they need the family to arrange. Write down the requested blood group, the component if specified, the collecting facility, the intended time and a contact person at that facility. A general request for “blood urgently” is hard for a volunteer to act on. BloodNet helps you discover people; it does not see the patient’s clinical plan or the blood bank’s inventory. Keeping the hospital’s request beside your search helps you avoid contacting the wrong group or asking a donor to travel to a facility that cannot receive them.'},
      {title:'Check the location the search is using',text:'Automatic country detection is a starting point, especially for a visitor who has not signed in. It can be approximate on a mobile network, a shared connection or a VPN. Open location preferences to review the selected country, and use precise location only if you want to confirm your position. A visitor helping a relative in another city should search for that city rather than assuming their own device location is the right one. Country and city labels on the resulting cards describe the listed service location, not a promise that the donor is currently standing nearby.'},
      {title:'Read the blood-group filter as a discovery tool',text:'Choose the group supplied by the hospital and review the city labels on the matching entries. The All groups view is useful for understanding the local network, but it is not a compatibility recommendation. A listed group is a profile field, not a new laboratory result. Do not substitute a different group because another card is closer or newer. If the required group is not represented, ask the hospital how to widen the search. The clinical team remains responsible for confirming the appropriate component, testing and compatibility.'},
      {title:'Understand broader and nearby results',text:'A small local network may have few entries for a particular filter. BloodNet can widen discovery when local matches are unavailable, and the interface explains that a broader area is being shown. Read the location on every card before contacting anyone. A result from another country is not a recommendation to travel across a border for donation. Ask the collecting facility whether a person can realistically reach an authorised collection site in time. A transparent wider result is more useful than pretending there are volunteers in a city where the directory has no matching entries.'},
      {title:'Turn a promising card into a confirmed arrangement',text:'Introduce yourself, explain that you found the volunteer through BloodNet and share the hospital’s request without forwarding private medical documents to strangers. Ask whether the person is willing to discuss the request and whether the proposed location and time are practical. A new account or active status can help organise discovery, but neither proves eligibility or guarantees a reply. Once a donor agrees to consider the request, connect them with the collecting service. Record who will confirm the appointment so that an unanswered message is never mistaken for a completed donation plan.'},
    ],
    steps:['Confirm the hospital’s request.','Review country and city preferences.','Select the requested blood group.','Contact a willing volunteer respectfully.','Confirm the arrangement with the collecting service.'],
    questions:[{question:'Does the nearest card guarantee the fastest donation?',answer:'No. Listed location, willingness, transport and collection capacity all need confirmation. Distance is only one part of coordination.'},{question:'Why might I see donors outside my selected city?',answer:'When matching local entries are unavailable, discovery can widen. Read the broader-results message and the location printed on each card.'},{question:'Can a profile replace a blood-group test?',answer:'No. Profile fields support discovery. The collecting service performs its own assessment and testing.'}],
    glossary:[{term:'Service city',meaning:'A location where a donor has indicated they can offer support.'},{term:'Active entry',meaning:'A listing currently included in the platform’s active directory; not a completed donation.'},{term:'Collecting service',meaning:'The hospital or authorised blood service responsible for donor assessment and collection.'}],sources:['donation','eligibility'],
  },
  {
    slug:'coordinate-an-urgent-blood-request',title:'Coordinate an urgent blood request without losing the details.',category:'Coordination',
    description:'A structured communication plan for families and volunteers: confirm the request, keep one coordinator, protect patient information and close the loop.',
    lead:'Clear communication is a practical way to reduce repeated calls and uncertain promises when a family is already under pressure.',
    chapters:[
      {title:'Let the treating facility define the request',text:'In an emergency, contact the treating facility or the local emergency service first. Ask the hospital whether it needs donor coordination, an appointment at a particular blood service or another action. The platform cannot determine urgency, prescribe a component or confirm stock. Keep a short request note that identifies the collection facility and a responsible contact without circulating a patient’s full medical file. If the treating team changes the plan, update the coordination note before more volunteers are contacted. A clear current instruction is more valuable than a large number of outdated forwarded messages.'},
      {title:'Use one person to maintain the live coordination note',text:'When several relatives contact donors independently, the same person may receive conflicting requests and the family may overestimate how many arrangements are confirmed. Choose a coordinator to track each contact as not contacted, awaiting a reply, discussing the request, referred to the facility or no longer needed. Keep that note within the family or approved coordination team. It should not become a public spreadsheet of phone numbers and diagnoses. Ask the hospital which parts of the request may be shared, and give volunteers a way to report that their availability has changed.'},
      {title:'Make the first message useful and respectful',text:'A first message can state the requested blood group, the collection facility, the proposed time and a way to reach the coordinator. Ask whether the volunteer is comfortable discussing the request. Avoid sending identity documents, test images, prescription photographs or payment demands as an introduction. People may be working, travelling, recovering from illness or simply unable to help. A refusal should be accepted without pressure. If a donor is willing to consider the request, move clinical questions to the collecting service rather than asking the family to decide medical eligibility through chat.'},
      {title:'Separate a reply from a completed arrangement',text:'“I may be able to help” is an expression of interest. It is not the same as a confirmed appointment, attendance, medical clearance or successful collection. Ask who will confirm the next step and how the family will learn whether the plan remains suitable. Keep uncertainty visible in the coordination note. If a volunteer becomes unavailable, update the note and consult the hospital about next steps rather than publishing the person’s details in a complaint. BloodNet listing counts cannot tell a family how many people will attend a particular collection session.'},
      {title:'Close the request when the hospital confirms the next step',text:'When the treating team says the immediate request has been handled or changed, notify the volunteers you contacted. This helps prevent unnecessary journeys and repeated follow-up calls. Share only the outcome that the patient or family has agreed can be shared. Do not publish a donor’s phone number as a thank-you without asking them. If more support may be needed later, keep the request distinct from the earlier arrangement and ask the hospital for an updated instruction. Maintaining a clear ending is part of considerate coordination, even when the wider medical situation is still ongoing.'},
    ],steps:['Contact the hospital first.','Assign one request coordinator.','Share a concise, current request.','Track interest and confirmation separately.','Notify volunteers when the request changes.'],
    questions:[{question:'Should I send reports to every donor I contact?',answer:'No. Share only what is necessary for coordination and let the authorised clinical team handle medical documents.'},{question:'Does an active donor count mean that many people can attend today?',answer:'No. It counts platform listings, not confirmed appointments, medically eligible donors or available blood units.'},{question:'Who decides whether a different blood group can help?',answer:'The treating and collecting teams. Do not make compatibility substitutions from directory information.'}],
    glossary:[{term:'Request coordinator',meaning:'The person keeping the family’s communication and status note consistent.'},{term:'Expression of interest',meaning:'A willingness to discuss a request, before practical and clinical checks.'},{term:'Closed loop',meaning:'The coordinator confirms what happened and tells contacted volunteers when the request changes.'}],sources:['donation','eligibility'],
  },
  {
    slug:'first-time-donor-planning',title:'Plan your first donation conversation with confidence.',category:'Volunteering',
    description:'Understand the difference between joining BloodNet and attending an authorised donation service, with a planning checklist and questions for the collection team.',
    lead:'Joining a volunteer network is a useful first step. The collection service will guide the medical assessment and donation appointment.',
    chapters:[
      {title:'Treat registration as an introduction, not a clearance',text:'A BloodNet account allows you to express willingness and maintain information that helps people discover your profile. It does not establish medical eligibility. Your name, selected blood group and active status are useful coordination details, but they do not replace the collecting service’s questions, tests or current national rules. If you are new to donation, ask an authorised service how its registration and assessment process works. You can learn about volunteering and keep an account even if a particular request or date is unsuitable for you.'},
      {title:'Choose a collection service before planning the journey',text:'Ask the relevant hospital or blood service whether it receives volunteer donors by appointment, referral or another local process. Confirm the address, opening arrangements and the information it wants you to bring. Do not rely on a forwarded map pin or an unfamiliar caller as the only confirmation of the destination. BloodNet’s location search identifies volunteer service areas; it is not a directory of verified opening hours for every collection site. Let the service give you its own preparation instructions, and contact it directly if anything about the request is unclear.'},
      {title:'Ask the service about your individual circumstances',text:'Eligibility can depend on current health, medical history, medicines, recent travel and the rules used by the collection service. This guide cannot assess those circumstances or supply a universal waiting period. Discuss questions privately with the authorised staff rather than placing personal medical details in a public biography. Be accurate during the service’s screening process, even if someone is urgently seeking support. A decision that donation is unsuitable on a particular occasion is a safety decision, not a failure to support the community.'},
      {title:'Keep your availability practical and changeable',text:'When setting a service city, think about where you can reasonably coordinate with a collecting facility. You do not need to promise unlimited travel or an immediate reply. If your circumstances change, update your active status and tell anyone with whom you have already discussed an arrangement. Avoid using an old profile note as evidence that you can donate on a new date. The service decides whether a new donation is appropriate; the platform’s availability setting simply helps other people understand whether you currently wish to receive coordination requests.'},
      {title:'Understand the choices around public discovery',text:'The normal donor-card experience and an optional search-engine profile are different ways of being found. A public search profile is an additional choice that can display your name, blood group, city, country and an introduction. Publishing a full phone number requires separate confirmation. Read those settings before enabling them, particularly if you are uncomfortable with unsolicited contact or cached search results. You can volunteer without making this additional profile public. Keep your introduction about coordination preferences and avoid publishing identity numbers, private diagnoses or information about other people.'},
    ],steps:['Find an authorised collecting service.','Ask how appointments and screening work.','Discuss personal eligibility privately.','Set realistic service cities and availability.','Review your public-profile preferences.'],
    questions:[{question:'Does creating an account mean I must donate?',answer:'No. A volunteer remains free to decline or withdraw from a request. A collecting service also needs to confirm eligibility.'},{question:'Where can I find the right preparation instructions?',answer:'Ask the service where you plan to attend. Its current instructions take priority over a general online checklist.'},{question:'Must I publish my phone number in Google to volunteer?',answer:'No. The additional public search profile and its full phone-number field are optional.'}],
    glossary:[{term:'Eligibility assessment',meaning:'The collecting service’s assessment of whether donation is appropriate.'},{term:'Availability status',meaning:'Your platform setting about receiving coordination requests.'},{term:'Public search profile',meaning:'An optional profile intended to be accessible to visitors and search engines.'}],sources:['eligibility','donation'],
  },
  {
    slug:'understand-blood-group-search',title:'Use blood-group search without mistaking it for a clinical match.',category:'Finding donors',
    description:'How to interpret blood-group filters, missing fields and local directory coverage while leaving transfusion decisions with qualified professionals.',
    lead:'A filter narrows a directory. It does not perform the testing or clinical decision-making needed for transfusion.',
    chapters:[
      {title:'Start with the group requested by the care team',text:'The treating team may give the family a specific request for a blood group or component. Use that instruction when searching. The directory’s labels organise volunteer entries so that people can contact potential supporters more efficiently. They are not a table of acceptable substitutions. If you are unsure what a label means, ask the hospital to clarify the request before contacting a large number of people. A volunteer’s profile may also be incomplete or based on information they entered themselves, so it should not be treated as an independently confirmed laboratory result.'},
      {title:'Read All groups as a network view',text:'All groups shows the wider set of entries available under the current location and search settings. It can help you see whether a local network exists and whether the city or country filter is too narrow for the task. It does not mean that every person shown can meet the same medical requirement. When returning to a specific request, choose the requested group again and check each card. A high total in All groups should not be interpreted as an assurance that a hospital has the required component available.'},
      {title:'Understand missing or unusual category information',text:'Some listings come from community organisations or manually maintained sources rather than an individual account with every field completed. A missing group is a missing directory field. It is not evidence of a rare type, universal compatibility or a medical exception. The useful response is to ask the relevant contact and collecting service for clarification. The interface should preserve uncertainty instead of inventing a group to make a card look complete. The same principle applies when an organ pledge is displayed with a blood-group field: a directory category is only part of a much larger professional assessment.'},
      {title:'Do not turn directory proportions into population estimates',text:'A city page may list several represented blood groups. That describes the entries in this particular platform snapshot. People join voluntarily, organisations contribute different amounts of data, and donors can offer support in several service cities. These factors mean the directory is not a representative sample of the city’s residents. A group appearing frequently here does not establish its population prevalence. When comparing pages, use the counts to understand discovery coverage and missing information, rather than to make claims about national blood-group distributions.'},
      {title:'Keep collection and testing in the professional pathway',text:'Once a willing volunteer is identified, follow the hospital or authorised blood service’s process. Clinical staff decide what testing, screening, collection and compatibility checks are required. Do not arrange a private transfusion because a profile and a request appear to share a label. If the requested category is difficult to find, ask the care team about its approved escalation options. BloodNet’s role is to make discovery and communication easier while leaving medical decisions with the people who have the clinical information, facilities and responsibility to make them.'},
    ],steps:['Copy the hospital’s requested group accurately.','Set the relevant location.','Filter entries and read missing fields honestly.','Confirm willingness and logistics.','Follow the collecting service’s testing process.'],
    questions:[{question:'Are the percentages on a directory a blood-group survey?',answer:'No. They describe participating listings and coverage, which can be incomplete and self-selected.'},{question:'What does a missing group mean?',answer:'Only that the directory does not have a usable value for that entry. Do not infer compatibility from it.'},{question:'Can this page tell me which group a patient should receive?',answer:'No. That decision belongs to the qualified treating and blood-service teams.'}],
    glossary:[{term:'Filter',meaning:'A way to narrow directory entries using stored fields.'},{term:'Component',meaning:'A blood product specified by the clinical service; ask that service to explain the request.'},{term:'Directory coverage',meaning:'Which locations and categories have participating entries in this platform.'}],sources:['blood','donation'],
  },
  {
    slug:'build-a-community-donor-network',title:'Build a donor network people can trust and keep using.',category:'Volunteering',
    description:'Practical principles for community organisers: permission, useful service areas, clear contact handling, accurate counts and respectful follow-up.',
    lead:'A smaller network with clear permission and reliable coordination can be more useful than a large list that nobody maintains.',
    chapters:[
      {title:'Invite participation rather than importing assumptions',text:'A phone number in an old group chat or spreadsheet is not a new permission to publish a searchable donor profile. Invite people to review the platform, understand the contact experience and maintain their own account where possible. Explain the difference between being available for coordination and publishing additional information on the open web. If you work with an organisation’s approved records, follow its process for permissions and corrections. Do not copy medical histories, identity documents or private group messages into public donor introductions.'},
      {title:'Describe the places the network can realistically serve',text:'A community may have a strong base in one city and only occasional support elsewhere. Use location information to describe that coverage accurately. Encourage volunteers to choose service cities they can reasonably support and update their availability when circumstances change. Avoid presenting every nearby city as fully covered merely because someone once travelled there. When the directory has a gap, a truthful description of that gap helps organisers decide where to build relationships. It is more useful than an optimistic nationwide claim that families cannot act on.'},
      {title:'Set a considerate communication routine',text:'Agree on who receives urgent coordination messages and how volunteers can decline or pause contact. The person sharing a request should know the hospital’s current instruction and should avoid repeatedly forwarding the same incomplete appeal. Make it easy for a volunteer to report a wrong number or an unsuitable time without being publicly criticised. A community network benefits from good records, but those records should contain only what is necessary for its role. Keep patient documents and personal health discussions within the authorised care pathway.'},
      {title:'Measure directory maintenance separately from donation outcomes',text:'A growing list of accounts can show that more people have joined the platform. It cannot by itself show that more transfusions took place or that a specific number of lives was saved. Track operational measures with clear definitions: participating entries, represented service cities, contact information corrected and requests whose coordination status was updated. If the community later records donation outcomes, define how they were confirmed and who consented to their use. Never relabel a registration count as a hospital collection statistic or as evidence from a representative survey.'},
      {title:'Make corrections and withdrawal part of ordinary maintenance',text:'People change jobs, move cities, replace phone numbers and reconsider what they want to share. Explain how to update an account, pause active status and withdraw an optional search profile. If a public page has already been indexed, be honest that external copies may take time to disappear. Respond to correction requests with the same care as registration requests. A trustworthy community network should not require someone to keep an inaccurate or unwanted public description simply because the information once helped the directory grow.'},
    ],steps:['Invite volunteers with a clear explanation.','Confirm realistic service areas.','Assign a request communication process.','Use precisely defined operational measures.','Provide an ordinary correction and withdrawal path.'],
    questions:[{question:'Can an organiser enable public phone indexing for every member?',answer:'No. The new public-profile controls belong to each registered donor and require separate phone publication consent.'},{question:'Is a larger list always a better network?',answer:'No. Permission, current details, realistic coverage and careful coordination determine how useful a list is.'},{question:'Can registration totals be described as successful donations?',answer:'No. Those are different measures and need different evidence.'}],
    glossary:[{term:'Operational measure',meaning:'A defined measure of how the platform or network functions.'},{term:'Outcome measure',meaning:'A measure of what happened after coordination, requiring its own confirmation method.'},{term:'Withdrawal',meaning:'A donor’s decision to stop publishing an additional public search profile.'}],sources:['donation','blood'],
  },
  {
    slug:'keep-donor-availability-current',title:'Keep your donor availability useful, honest and up to date.',category:'Volunteering',
    description:'How active status, service cities, profile updates and public search preferences work together without implying medical eligibility.',
    lead:'An accurate availability signal helps other people coordinate respectfully. It should always remain a choice you can change.',
    chapters:[
      {title:'Use active status for willingness to receive requests',text:'The active setting helps the platform decide which entries belong in an active donor search. It should describe whether you currently wish to receive coordination requests, not whether a hospital has medically cleared you to donate. If you are unavailable, changing that setting is a useful way to reduce misleading discovery results. A family that has already contacted you may not see the change immediately, so communicate directly about an existing arrangement. Do not rely on a website switch as the only way to cancel a planned appointment.'},
      {title:'Keep service cities relevant to your real routine',text:'A service city describes an area in which you have offered support. It can be different from the location your device happens to report today. Review those cities when you move or when your travel pattern changes. The platform may apply limits or waiting periods to city changes; the profile interface explains the current options. Keep the description practical rather than adding places merely to appear in more searches. For a particular request, confirm the actual collecting facility and time with the coordinator before making a journey.'},
      {title:'Understand why a new account appears before older entries',text:'The main feed prioritises registration recency within its current filters. That ordering helps people see newly interested volunteers; it is not a ranking of generosity, clinical suitability or reliability. Editing an older profile should not be treated as a new registration. Other location-specific views can organise discovery differently according to their purpose. Whatever the order, the person contacting a donor still needs to confirm willingness and logistics. A card near the top of a list does not carry a medical assurance that the platform cannot provide.'},
      {title:'Review your contact and publication choices together',text:'A phone number used for an account and a phone number explicitly published on a search-engine profile are different choices. If your number changes, review the additional public profile as well as your ordinary account details. Only enable full phone publication if you are comfortable with that number being visible to anyone and potentially copied. A public biography should explain your coordination preferences without disclosing private medical information. If you no longer want the additional profile online, use the withdrawal control rather than relying on a small wording change to discourage contact.'},
      {title:'Treat update dates as information about records',text:'A date printed on a directory tells a reader something about the stored record or publication settings. It does not prove the donor is available at that exact moment, has recently been screened or can meet a particular hospital requirement. This distinction matters when an appeal is urgent and a family is tempted to treat any recent-looking page as a confirmation. Keep your own details accurate, reply when practical, and let the collecting service decide eligibility. A reliable directory makes uncertainty understandable instead of using timestamps as a substitute for real coordination.'},
    ],steps:['Review your active status.','Check realistic service cities.','Correct your contact information.','Review optional search publication.','Tell existing coordinators about changed plans.'],
    questions:[{question:'Does active mean medically eligible today?',answer:'No. It is a platform availability signal. The collecting service performs the medical assessment.'},{question:'Will changing a health field make my account newly registered?',answer:'No. Registration order and later profile edits represent different events.'},{question:'Does a recent update guarantee a reply?',answer:'No. Contact availability and willingness still need confirmation.'}],
    glossary:[{term:'Registration recency',meaning:'How recently an account or source entry joined the directory.'},{term:'Record update',meaning:'A change to stored profile or publication information.'},{term:'Active status',meaning:'The platform setting used to include an entry in active discovery.'}],sources:['eligibility','donation'],
  },
];

DONATION_GUIDES.push(
  {
    slug:'understand-organ-donation-pledges',title:'Understand what an organ-donation pledge can—and cannot—do.',category:'Organ donation',
    description:'Learn how a willingness-to-donate entry differs from a legal donor register, a clinical assessment, organ allocation and a confirmed transplant arrangement.',
    lead:'A pledge starts a conversation. It does not replace a regulated transplant pathway, the donor’s continuing consent or the recipient’s clinical assessment.',
    chapters:[
      {title:'Read a pledge as an expression of willingness',text:'An organ entry on BloodNet describes a person’s stated willingness or a contributed directory entry. It is not an organ available for immediate collection. The platform does not assess surgical suitability, confirm compatibility or allocate an organ to a recipient. A family should begin with the treating transplant centre and ask what kind of support is appropriate. Treating every pledge as a ready clinical match creates expectations that a public directory cannot justify. The useful role of a listing is to support a careful, permission-based conversation within an authorised medical process.'},
      {title:'Distinguish a platform profile from an official register',text:'Countries and jurisdictions have their own laws and official processes for donation and consent. A BloodNet profile is not automatically an entry on a government or health-service donor register. Nor does a ticked organ category constitute every form of consent that a transplant team may require. If you want to record an official donation decision, consult the relevant health authority in your jurisdiction. This guide links to general ethical and service information but does not assume that the rules of one country apply to a person living somewhere else.'},
      {title:'Keep clinical assessment separate from directory categories',text:'An organ category, a blood-group field and a location label are useful ways to organise discovery. They are only a small part of what a transplant service needs to consider. A transplant team may need a detailed assessment of donor and recipient circumstances, and it will explain the applicable pathway. Do not send private test results to an unknown contact in an attempt to complete that assessment yourself. A public biography should not be used as a substitute for a confidential clinical consultation, and a platform status should never be presented as surgical clearance.'},
      {title:'Protect the freedom to decline or reconsider',text:'Willingness must remain voluntary. A person may decide not to discuss a request, may wish to speak privately with a professional or may change their mind. Respect that decision without pressure or public criticism. The WHO guiding principles provide a general ethical framework for donation and transplantation; the lawful consent process is determined by the relevant jurisdiction and clinical service. Avoid treating a public pledge, an emotional appeal or a family relationship as evidence that someone owes a donation. Keeping a safe boundary around the conversation is part of responsible coordination.'},
      {title:'Do not turn a pledge directory into an organ marketplace',text:'BloodNet must not be used to buy, sell or broker organs. An offer involving payment, coercion or an unregulated procedure should not be treated as a useful shortcut around a transplant centre. Keep the authorised clinical team involved, use the platform’s reporting options for suspicious conduct and avoid forwarding another person’s documents or contact details. A country-level count on this site measures directory coverage; it does not measure lawful transplant supply or the number of people suitable for a procedure. Ethical discovery depends on preserving these distinctions.'},
    ],steps:['Discuss the need with a transplant centre.','Read the pledge as willingness only.','Use the official consent process where you live.','Keep assessment with qualified professionals.','Respect refusal and report coercion.'],
    questions:[{question:'Is a BloodNet pledge an official national donor registration?',answer:'No. Follow the relevant health authority’s official process if you want to record a legal donation decision.'},{question:'Does matching the listed organ and blood group establish suitability?',answer:'No. A regulated transplant service must assess the clinical and consent requirements.'},{question:'Can someone withdraw from a donation conversation?',answer:'Yes. Willingness must remain voluntary, and a public profile does not create an obligation to proceed.'}],
    glossary:[{term:'Pledge',meaning:'An expression of willingness recorded on the platform.'},{term:'Official donor register',meaning:'A jurisdiction’s recognised system for recording a donation decision.'},{term:'Allocation',meaning:'The regulated process for deciding how a donated organ is offered; BloodNet does not perform it.'}],sources:['transplant','living'],
  },
  {
    slug:'coordinate-with-a-transplant-centre',title:'Keep transplant coordination inside the authorised care pathway.',category:'Organ donation',
    description:'A practical communication guide for patients, families and potential volunteers, with clear boundaries around documents, consent and centre-led assessment.',
    lead:'The most useful next step is often a clearer question for the transplant team, rather than a wider public appeal.',
    chapters:[
      {title:'Ask the treating team to explain the pathway',text:'A transplant conversation can involve several different processes, and a family should not have to infer them from a directory. Ask the treating service which team is responsible for the next step, what information it can receive and how a potential volunteer should contact it. BloodNet cannot decide whether a living-donor discussion, an official register or another route is appropriate for a particular patient. Keep the centre’s instructions in a private coordination note, and update that note if the clinical plan changes. This keeps a public appeal from promising something the care team has not requested.'},
      {title:'Share enough to make contact, not an entire medical file',text:'A potential volunteer may need to know how to contact the authorised team, but does not automatically need a recipient’s full report collection, identity documents or private contact history. Ask the clinical service how it wants information transferred and who may access it. The platform’s private medical-record features are intended for account-level record keeping; they do not make those records public evidence for an appeal. If a family wants to tell a personal story, obtain the patient’s permission and separate that story from clinical claims that only the treating professionals can confirm.'},
      {title:'Allow the potential donor to speak privately',text:'A willing person may have questions they do not want to raise in a family group or public comment thread. An authorised service can explain how it handles assessment, consent and confidential discussion. Give the person that route rather than asking them to justify every hesitation to a coordinator. The NHS living-donation information is one example of a service describing a structured assessment process; it is UK-specific and should not be treated as a universal legal checklist. Ask the centre in the relevant jurisdiction about its own current requirements.'},
      {title:'Keep practical support distinct from clinical promises',text:'Families and communities can help with communication, directions and ordinary planning, but should not promise a transplant date, compatibility result or clinical outcome based on a profile. Keep each coordination status precise: a contact was made, a person asked for information, or the centre received a query. These statements are different from a completed assessment or procedure. If an online contact claims to bypass the centre, demands payment for an organ or asks for unnecessary documents, pause the conversation and consult the authorised team. A fast-sounding offer is not evidence of a safe or lawful pathway.'},
      {title:'Review the plan and close public appeals responsibly',text:'If the care team changes its advice, make sure the coordinator stops repeating an outdated request. Inform people who have already offered to discuss support, without sharing clinical updates beyond what the patient has agreed can be disclosed. Do not keep someone’s name and phone number in a public appeal indefinitely because they once responded. A useful coordination record explains what was confirmed, what remains uncertain and who is responsible for the next action. It should never be used to pressure a volunteer or to imply that a directory listing guarantees a medical outcome.'},
    ],steps:['Identify the responsible transplant team.','Ask how potential volunteers should make contact.','Use the centre’s confidential document process.','Record practical steps without clinical promises.','Update or close appeals when advice changes.'],
    questions:[{question:'Can BloodNet confirm a transplant date?',answer:'No. Assessment, allocation and treatment planning belong to the authorised clinical services.'},{question:'Should all reports be attached to a public appeal?',answer:'No. Ask the treating team what is necessary and use its approved confidential transfer process.'},{question:'Are UK living-donation rules valid everywhere?',answer:'No. UK service material is a clearly labelled example; local law and the relevant centre’s requirements apply.'}],
    glossary:[{term:'Authorised pathway',meaning:'The clinical and lawful process explained by the responsible transplant service.'},{term:'Confidential discussion',meaning:'A private conversation with the appropriate professional team.'},{term:'Coordination status',meaning:'A precise description of an administrative step, not a clinical result.'}],sources:['transplant','living'],
  },
  {
    slug:'protect-medical-records',title:'Keep reports and prescriptions useful without making them public.',category:'Privacy & data',
    description:'Organise report uploads, camera captures and prescriptions while separating private medical records from public donor discovery and search profiles.',
    lead:'A well-organised record should be easy for its owner to find and difficult to confuse with information intended for the open web.',
    chapters:[
      {title:'Keep the medical timeline separate from your public introduction',text:'BloodNet’s medical-record features and its public donor search have different purposes. The record timeline helps you keep reports and prescriptions in your account. A public introduction explains volunteering preferences to visitors. Do not copy a diagnosis, identification number or report photograph into a biography simply to make a search page longer. A useful public profile can describe how you prefer to coordinate through a hospital without disclosing a private clinical history. Review the public preview before publishing so that the distinction remains clear.'},
      {title:'Check previews before confirming a batch upload',text:'When selecting several report images, use the preview to verify that each page belongs to the intended record. Similar filenames and camera rolls can make it easy to mix one person’s report with another person’s document. Check page order, legibility and the title of the report before saving. A camera capture is still a document upload; look for cropped dates, missing corners and unreadable text. Compression reduces storage size, but a smaller file is useful only if the information remains legible. Retain your original document where appropriate for your own records.'},
      {title:'Use clinical dates to organise the timeline',text:'An upload date and a report date describe different events. Enter the test or report date when available so that the timeline can help you find older information after a later upload. Add the test title, category, facility and clinician when those fields are relevant and known. Do not guess a date or a doctor’s name just to complete a form. If a record contains several pages for one test, keep them together; if a batch contains different tests, use their individual titles and dates so the timeline remains meaningful.'},
      {title:'Distinguish your uploaded prescription from a doctor-delivered one',text:'A prescription uploaded from a photograph and one delivered through the platform’s doctor integration have different origins. Preserve the doctor’s name and written date for a patient-uploaded record, and read the timeline’s origin labels rather than assuming every entry was sent directly by a clinician. Storage and organisation do not authenticate the contents of a document or make it current medical advice. If instructions are unclear, outdated or inconsistent, ask the prescribing professional. Do not change treatment because a different entry appears higher in a sorting view.'},
      {title:'Share records through an appropriate care process',text:'Only provide records to people who need them for a legitimate purpose and through a method you and the receiving service understand. A public donor search result should not contain your medical-record files, patient identifier, private account email or document history. Account administration and a permission-checked audit are also different from a public page. If you notice the wrong person’s document, an unexpected public link or an account-access problem, stop further sharing and report the issue. Keep a record of which document is affected without reposting the document more widely.'},
    ],steps:['Confirm the intended patient and record.','Preview each selected image.','Enter accurate test and prescription dates.','Check the timeline’s origin labels.','Keep public biographies free of private documents.'],
    questions:[{question:'Does a public donor profile include my reports?',answer:'No. The additional public profile uses an explicit set of donor fields and does not include medical files or patient identifiers.'},{question:'Is an uploaded prescription automatically verified by BloodNet?',answer:'No. The timeline preserves its origin; storage is not clinical authentication.'},{question:'Should I invent a missing report date?',answer:'No. Keep uncertain information identifiable and check the original document or the issuing service.'}],
    glossary:[{term:'Clinical date',meaning:'The date of a test, report or prescription rather than the later upload event.'},{term:'Origin label',meaning:'An indication of whether a record was uploaded by the patient or delivered through the doctor pathway.'},{term:'Public preview',meaning:'The additional search profile visible to an ordinary visitor, not the private medical timeline.'}],sources:[],
  },
  {
    slug:'travel-and-donor-search',title:'Search for support in the right place when you are away from home.',category:'Finding donors',
    description:'Use country preferences, service cities and broader results carefully when coordinating for another city, travelling or using a VPN.',
    lead:'Your device’s location, your home city and the place where a patient needs support can be three different places.',
    chapters:[
      {title:'Decide whose location matters for this request',text:'A visitor may be at work in one city while helping a relative in another. Start with the collecting facility’s location rather than assuming the search should use your current position. Write the relevant country and city clearly, especially where city names occur in more than one country. A card that looks geographically familiar can still refer to a different jurisdiction. The platform’s service-city fields help organise discovery, but the coordinator should confirm the full facility address before suggesting that a volunteer travel.'},
      {title:'Understand automatic country detection as an approximation',text:'An IP-based location can reflect a network gateway, mobile operator or VPN endpoint instead of a person’s precise position. It is useful for offering an initial country preference without repeated browser permission prompts. It should not be described as a verified live location. Review the selected country before judging the search results. If the setting does not match the request you are coordinating, choose the relevant country manually. This is particularly useful when you are abroad or using a work network that sends traffic through another region.'},
      {title:'Use precise location only when it helps your own search',text:'The precise-location control asks the browser for permission because it uses a different level of location information. You can decline and continue using an approximate or manually selected area. If you are coordinating for another person’s hospital, confirming your own precise position may not improve the search at all. Do not interpret a successful location request as a medical or logistical confirmation. It identifies a device position for discovery; it cannot establish that a donor can reach the facility, has transport or meets a collection service’s requirements.'},
      {title:'Read cross-border results with particular care',text:'A broader result may show a volunteer in another country when the selected local area has no matching entries. That prevents a directory from hiding all available information, but it does not make cross-border donation practical or appropriate. Transport, local collection rules and clinical requirements are outside the directory’s ability to confirm. Ask the authorised service what options it recommends. Never treat a nearby-country label as permission to arrange an unregulated medical journey or move blood or organs across a border yourself.'},
      {title:'Keep travel history questions with the collecting service',text:'A donor’s recent travel can be relevant to a collecting service’s assessment, but a city filter cannot answer those questions. Do not use the country displayed on a profile to infer a person’s travel history, health status or eligibility. Discuss the service’s current requirements privately and accurately. If you are a volunteer updating service cities after moving, describe realistic coordination locations and review your availability separately. The directory should help the right people have a conversation, while the clinical service remains responsible for deciding whether a donation can proceed.'},
    ],steps:['Locate the collecting facility.','Check both country and city names.','Review automatic location preferences.','Read wider-result labels carefully.','Confirm travel and eligibility questions with the service.'],
    questions:[{question:'Why can my detected country be wrong?',answer:'Shared networks, mobile routing and VPNs can make approximate IP-based location different from your actual location.'},{question:'Do I have to grant precise-location permission?',answer:'No. Manual preferences and approximate discovery remain available.'},{question:'Does a nearby-country result recommend medical travel?',answer:'No. Ask the authorised collecting or transplant service about suitable next steps.'}],
    glossary:[{term:'Approximate location',meaning:'A network-derived estimate used as an initial discovery preference.'},{term:'Precise location',meaning:'A device-position request controlled by the browser’s permission process.'},{term:'Cross-border result',meaning:'A directory entry from a different country, not an approved clinical travel plan.'}],sources:['eligibility'],
  },
  {
    slug:'read-donor-data-responsibly',title:'Read donor data with the definitions still attached.',category:'Privacy & data',
    description:'Understand unique entries, city coverage, active status, timestamps and the difference between platform data and published global blood-system reporting.',
    lead:'A number becomes useful when the reader knows what was counted, when it was counted and what it cannot establish.',
    chapters:[
      {title:'Identify the unit being counted',text:'BloodNet’s active blood-directory total counts active registered, manual and community source entries once per source listing. It does not automatically establish that every source row is a unique person across every organisation. A city count can include the same registered volunteer in several service cities. Keep those definitions beside a chart or summary. The word “donor” is convenient in an interface, but an analytical explanation should distinguish participating directory entries, individuals, organisations, appointments, blood units and completed donations. These are different units and cannot be substituted for one another.'},
      {title:'Separate global totals from city coverage',text:'Adding the counts from several city pages can count a multi-city volunteer more than once. The network-wide total uses a different rule: it counts active source entries once. A country coverage view therefore labels a sum of city listings as coverage, not as an unduplicated national headcount. This distinction also matters when comparing blood and organ categories; a person may have several pledges. Do not combine those categories into a claim about unique people without a method designed for that purpose.'},
      {title:'Do not compare platform registrations with a population survey',text:'The people represented in a volunteer directory chose to register or were included through an authorised source. They are not a random sample of the population. The platform does not know how many unregistered donors live in a city or how many people donated outside the network. WHO’s blood-system reporting is a separate source with its own definitions, reporting period and coverage. Its global figures can provide context, but should never be rewritten as local BloodNet findings or combined with registration totals to invent a national donation rate.'},
      {title:'Read dates as provenance rather than certainty',text:'A snapshot retrieval time describes when the platform read data. A record-change time describes when a stored entry or service location was updated. A report publication date describes an external source. Keeping these dates separate makes a page easier to assess. None of them proves that a volunteer will answer a call today. Likewise, a page being rebuilt or viewed does not mean the underlying medical information was newly checked. A careful interface explains the meaning of each date instead of presenting every timestamp as a fresh clinical verification.'},
      {title:'Prefer transparent limitations over impressive-looking claims',text:'A useful data explanation can say that a city has few participating entries, that a category is missing or that the source is self-reported. Those statements help readers choose the next step. Invented success rates, unsupported “lives saved” totals and borrowed survey figures relabelled as local findings do the opposite. The network pages link to real location directories and explain their counting rules so that a reader can inspect the coverage. Treat them as operational discovery information, and ask the relevant health service for clinical or population-level statistics.'},
    ],steps:['Read the metric’s unit.','Check its geographic scope.','Check the source and reporting period.','Look for overlap and missing fields.','Use the figure only for the purpose it supports.'],
    questions:[{question:'Can I add city counts to obtain a unique worldwide donor total?',answer:'No. A person can be represented in more than one service city. Use the separately defined global active-entry total.'},{question:'Are BloodNet counts representative national statistics?',answer:'No. They describe participating platform entries and coverage.'},{question:'Does a record update date prove clinical verification?',answer:'No. It is a timestamp about stored information, not a new assessment by a collecting service.'}],
    glossary:[{term:'Unit of analysis',meaning:'The thing counted: for example a source listing, city coverage entry or completed collection.'},{term:'Provenance',meaning:'Where information came from and which dates and definitions belong to it.'},{term:'Self-selection',meaning:'Participation based on choosing to join rather than representative population sampling.'}],sources:['blood'],
  },
  {
    slug:'donor-privacy-and-public-profiles',title:'Understand your public donor profile and privacy options.',category:'Privacy & data',updatedAt:'2026-10-17',
    description:'Learn how administrator-approved donor articles appear publicly, which information stays private and how to request corrections or removal.',
    lead:'Being easier to find can be helpful. It should also be a deliberate choice about which information becomes public.',
    chapters:[
      {title:'Know what the additional search profile contains',text:'An administrator-approved public donor article can display the donor’s name, registered blood group, city, country and an editorial introduction based on recorded profile details. This is separate from the private account screen and medical timeline. It does not include the account email, date of birth, patient identifier, uploaded reports or prescriptions. Read the public page as an ordinary visitor would see it. A profile intended for search engines is accessible outside the BloodNet community, so accuracy and appropriate publication decisions matter.'},
      {title:'Treat full phone publication as a separate decision',text:'A person can want a public volunteer introduction without wanting a phone number copied into search results. The administrator reviews full phone visibility separately and records the publication decision. If enabled, the number is visible in the page and can be used as structured contact information. That may make contact easier, but it may also lead to unsolicited messages or copies outside the platform. The platform cannot promise which search engine will index the number, when it will appear or where it will rank.'},
      {title:'Keep the article grounded in real profile details',text:'BloodNet provides article templates that an administrator can review against the donor’s recorded name, blood group and location. These are editorial articles, rather than quotations or personal stories written by the donor. A template must not invent completed donations, medical clearance, clinical qualifications or immediate availability. Contact the platform if a detail is inaccurate or no longer current. An article should help someone start a practical conversation with a local volunteer while leaving assessment and collection decisions with the authorised service.'},
      {title:'Ask an administrator to correct or withdraw publication',text:'Public donor article controls are in the administrator’s user profile view. They are not displayed in an ordinary user account, and users cannot publish an article through their account settings. If a public detail is wrong or you want the article removed, contact BloodNet and identify the public profile URL. An administrator can review the request and withdraw publication. Withdrawal removes the original public article and its sitemap entry, but cannot remotely erase screenshots or copies already held by other people. Search engines may take time to update their results.'},
      {title:'Understand what discoverability cannot promise',text:'A searchable profile provides a relevant page that a search engine may choose to crawl and index. It cannot ensure first place for a name or phone number, and a common name may match many unrelated people. BloodNet should not create thousands of duplicate phone-format pages or misleading descriptions to force visibility. The useful goal is a clear, permission-based profile with accurate information, a stable link and an understandable withdrawal process. If being publicly identifiable no longer suits your circumstances, you can request withdrawal without changing the value of your willingness to volunteer.'},
    ],steps:['Read the public profile and check its details.','Keep your recorded location and availability current.','Contact BloodNet about inaccuracies.','Ask for a review of phone visibility if needed.','Request withdrawal through the platform when needed.'],
    questions:[{question:'Can I publish an article from my account?',answer:'No. An administrator reviews and controls publication in the admin user profile view.'},{question:'Must a public article display the full phone number?',answer:'No. Full phone visibility is a separate publication setting reviewed by the administrator.'},{question:'Does withdrawal immediately delete every search result?',answer:'No. The original profile becomes unavailable, but external caches and copies may take time to change or may be outside the platform’s control.'}],
    glossary:[{term:'Indexing',meaning:'A search engine’s decision to include a page in its searchable collection.'},{term:'Separate phone consent',meaning:'An additional confirmation before a full phone number is published on the new search profile.'},{term:'Cached copy',meaning:'A copy kept outside the current live page, which may not change immediately after withdrawal.'}],sources:[],
  }
);

export const getDonationGuide = (slug:string) => DONATION_GUIDES.find(guide=>guide.slug===slug);
